changeSet.sql:
CREATE EXTENSION IF NOT EXISTS pgcrypto;

ALTER TABLE profiles DROP CONSTRAINT IF EXISTS profiles_user_fk;

ALTER TABLE users ADD COLUMN IF NOT EXISTS id_uuid UUID DEFAULT gen_random_uuid();
UPDATE users SET id_uuid = gen_random_uuid() WHERE id_uuid IS NULL;
ALTER TABLE users ALTER COLUMN id_uuid SET NOT NULL;

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS user_id_uuid UUID;
UPDATE profiles p
SET user_id_uuid = u.id_uuid
FROM users u
WHERE p.user_id = u.id;
ALTER TABLE profiles ALTER COLUMN user_id_uuid SET NOT NULL;

ALTER TABLE users DROP CONSTRAINT IF EXISTS users_pkey;
ALTER TABLE users DROP COLUMN id;
ALTER TABLE users RENAME COLUMN id_uuid TO id;
ALTER TABLE users ADD CONSTRAINT users_pkey PRIMARY KEY (id);

DROP INDEX IF EXISTS idx_profiles_user_id;
ALTER TABLE profiles DROP CONSTRAINT IF EXISTS profiles_user_id_key;
ALTER TABLE profiles DROP COLUMN user_id;
ALTER TABLE profiles RENAME COLUMN user_id_uuid TO user_id;
ALTER TABLE profiles ADD CONSTRAINT profiles_user_id_key UNIQUE (user_id);
ALTER TABLE profiles ADD CONSTRAINT profiles_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE INDEX idx_profiles_user_id ON profiles(user_id) WHERE deleted_at IS NULL;
